from typing import List
from collections import defaultdict

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        best = cur = nums[0]
        for a in nums[1:]:
            cur = max(a, cur + a)
            best = max(best, cur)

        if best <= 0:
            return best

        dp = defaultdict(int)
        ans = best

        for a in nums:
            for_delete = dp[a] if a < 0 else 0

            if a < 0:
                dp[a] = max(dp[a], cur) - a

            cur = max(a, cur + a)
            ans = max(ans, cur + max(dp.values(), default=0))

        return ans
